typedef unsigned int size_t;
typedef float rational_t;
typedef int entity_flavor_t;

class entity_id {};

class stringx
{
  void* p;
  int n;
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
};

stringx operator+(const stringx&, const char*);

class chunk_file
{
  char storage[280];
public:
  chunk_file();
  ~chunk_file();
  void open(const stringx&, int mode = 1);
};

void serial_in(chunk_file&, stringx*);
void* operator new(size_t, unsigned int, const char*, int);
void operator delete(void*);

class entity
{
  char storage[512];
protected:
  static chunk_file* my_fs;
public:
  entity(const entity_id&, entity_flavor_t, unsigned int flags = 0);
  void set_active(bool);
  void set_stationary(bool);
  void set_radius(rational_t);
};

class item : public entity
{
protected:
  bool preload_script_called;
  bool item_script_called;
  bool linked;
  int usage_type;
  stringx name;
  int count;
  int default_count;
  bool picked_up;
  rational_t pickup_timer;
  rational_t icon_scale;
  rational_t interface_orientation;
  int max_num;
public:
  item(const stringx&, const entity_id&, entity_flavor_t, bool, bool, bool);
  void read_item_data(chunk_file&, stringx&);
};

#define NEW new(0, "C:/KS/SRC/item.cpp", __LINE__)
#define assert(x) ((void)0)
#define PI 3.14159265358979323846f

item::item( const stringx& item_type_filename,
            const entity_id& _id,
            entity_flavor_t _flavor,
            bool _active,
            bool _stationary,
            bool delete_stream)
  :   entity( _id, _flavor )
{
  //vr_pmesh::push_optimize_static_mesh_for_d3d_disallowed();
  assert (my_fs == NULL);

  set_active( true );
  set_stationary( false );

  my_fs = NEW chunk_file();
  stringx ent_name(item_type_filename+".ent");
  my_fs->open(ent_name);

  stringx dummy;
  // Strip Entity Flavor
  serial_in(*my_fs, &dummy);

  serial_in( *my_fs, &dummy );
  assert( dummy == "item:" );
  read_item_data( *my_fs, dummy );

  // This is probably holding place for a value from the file <<<<.
  set_radius(0.25f);
  default_count = count = 1;
//  need_to_initialize = false;

#if _ENABLE_WORLD_EDITOR
  original_count = count;
#endif

  if ( delete_stream )
  {
    assert(my_fs);
    delete my_fs;
    my_fs = NULL;
  }

  picked_up = false;
  pickup_timer = 0;

  max_num = 10;

  icon_scale = 1.0f;

  interface_orientation = 225.0f * PI / 180.0f;

//  set_gravity( false );
//  set_physical( false );

//  dread_net_use_cue = dread_net::UNDEFINED_AV_CUE;

  preload_script_called = false;
  item_script_called = false;
  linked = false;
  //vr_pmesh::pop_optimize_static_mesh_for_d3d_disallowed();
}
